#include <stdlib.h>
#include <string.h>
static void bt(char*h,int n,int*used,char*cur,int d,char mid,char***o,int*c,int*cap){if(d==n){if(*c==*cap){*cap*=2;*o=realloc(*o,*cap*sizeof(char*));}char*s=malloc(2*n+(mid?2:1));for(int i=0;i<n;i++)s[i]=cur[i];int p=n;if(mid)s[p++]=mid;for(int i=n-1;i>=0;i--)s[p++]=cur[i];s[p]=0;(*o)[(*c)++]=s;return;}for(int i=0;i<n;i++){if(used[i]||(i&&h[i]==h[i-1]&&!used[i-1]))continue;used[i]=1;cur[d]=h[i];bt(h,n,used,cur,d+1,mid,o,c,cap);used[i]=0;}}char** generatePalindromes(char*s,int*rs){int cnt[256]={0},odd=0;char mid=0;for(int i=0;s[i];i++)cnt[(unsigned char)s[i]]++;for(int i=0;i<256;i++)if(cnt[i]&1){odd++;mid=i;}if(odd>1){*rs=0;return NULL;}int n=strlen(s)/2,k=0;char*h=malloc(n+1);for(int i=0;i<256;i++)for(int j=0;j<cnt[i]/2;j++)h[k++]=i;int*used=calloc(n,sizeof(int));char*cur=malloc(n);int cap=16,c=0;char**o=malloc(cap*sizeof(char*));bt(h,n,used,cur,0,mid,&o,&c,&cap);free(h);free(used);free(cur);*rs=c;return o;}
